#include <iostream>

long long factorial(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

int sumDigits(int n) {
    if (n < 10) {
        return n;
    }
    return n % 10 + sumDigits(n / 10);
}

int main() {
    std::cout << "factorial(10) = " << factorial(10) << '\n';
    std::cout << "sumDigits(4096) = " << sumDigits(4096) << '\n';
    return 0;
}

