#include <iostream>
#include <string>
#include <vector>

const int DR[4] = {-1, 1, 0, 0};
const int DC[4] = {0, 0, -1, 1};

int floodFill(const std::vector<std::string>& grid, std::vector<std::vector<bool>>& visited, int r, int c) {
    const int rows = static_cast<int>(grid.size());
    const int cols = static_cast<int>(grid[0].size());
    if (r < 0 || r >= rows || c < 0 || c >= cols) {
        return 0;
    }
    if (grid[r][c] != '#' || visited[r][c]) {
        return 0;
    }
    visited[r][c] = true;
    int size = 1;
    for (int d = 0; d < 4; ++d) {
        size += floodFill(grid, visited, r + DR[d], c + DC[d]);
    }
    return size;
}

int main() {
    const std::vector<std::string> grid = {
        "##..#",
        "#...#",
        "..#..",
        ".###.",
    };
    const int rows = static_cast<int>(grid.size());
    const int cols = static_cast<int>(grid[0].size());
    std::vector<std::vector<bool>> visited(rows, std::vector<bool>(cols, false));
    std::vector<int> sizes;
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (grid[r][c] == '#' && !visited[r][c]) {
                sizes.push_back(floodFill(grid, visited, r, c));
            }
        }
    }
    std::cout << "islands: " << sizes.size() << '\n';
    std::cout << "sizes:";
    for (int s : sizes) {
        std::cout << ' ' << s;
    }
    std::cout << '\n';
    return 0;
}

