    const int cols = static_cast<int>(grid[0].size());
    if (r < 0 || r >= rows || c < 0 || c >= cols) {
        return 0;
    }
    if (grid[r][c] != '#' || visited[r][c]) {
        return 0;
    }
    visited[r][c] = true;
    int size = 1;
    for (int d = 0; d < 4; ++d) {
        size += floodFill(grid, visited, r + DR[d], c + DC[d]);
    }
    return size;
}

int main() {
    int rows = 0;
    int cols = 0;
    std::cin >> rows >> cols;
    std::vector<std::string> grid(rows);
    for (int r = 0; r < rows; ++r) {
        std::cin >> grid[r];
