void printPath(const std::vector<int>& path) {
    std::cout << '{';
    for (std::size_t i = 0; i < path.size(); ++i) {
        if (i > 0) {
            std::cout << ' ';
        }
        std::cout << path[i];
    }
    std::cout << "}\n";
