void combine(int start, int n, int k, std::vector<int>& path) {
    if (static_cast<int>(path.size()) == k) {
        printPath(path);
        return;
    }
    for (int i = start; i <= n; ++i) {
        path.push_back(i);
        combine(i + 1, n, k, path);
        path.pop_back();
    }
}

